use vstd::prelude::*;

verus! {
    // where_fn takes three vectors of equal length:
    //   - a boolean mask `condition`
    //   - two float vectors `x` and `y`
    // It returns a new float vector `result` of the same length,
    // where for each index i,
    //   result[i] = if condition[i] { x[i] } else { y[i] }.
    fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> (result: Vec<f32>)
        requires
            condition.len() == x.len(),
            x.len() == y.len(),
        ensures
            result.len() == condition.len(),
            forall |i: usize|
                i < condition.len() ==>
                    result[i] == (if condition[i] { x[i] } else { y[i] }),
    {
        let n = condition.len();
        // Pre-allocate the result vector with capacity n
        let mut result: Vec<f32> = Vec::with_capacity(n);
        let mut i: usize = 0;
        // Build up result one element at a time
        while i < n
            invariant
                // i always stays within [0, n]
                i <= n,
                // result.len() tracks how many elements we've pushed
                result.len() == i,
                // For all j < i, result[j] has the desired value
                forall |j: usize|
                    j < i ==>
                        result[j] == (if condition[j] { x[j] } else { y[j] }),
            decreases n - i,
        {
            if condition[i] {
                result.push(x[i]);
            } else {
                result.push(y[i]);
            }
            i += 1;
        }
        result
    }
}

